
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_b94_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_b94", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.001802190005770e-01, -9.519282332688975e-02, -8.882586123481256e-02, -8.103091719054759e-02, -7.196940583645910e-02, -6.206109641233770e-02, -5.194011978106823e-02, -4.218646329860262e-02, -3.285664237906612e-02, -2.431096085945190e-02, -2.216251376479427e-02, -4.210488680058020e-02, -4.589016720289939e-02, -2.703142260656052e-02, -1.317020618363914e-02, -4.973077846390173e-03, -9.995109258108376e-04, -7.666131269266403e-05, -1.565865080732941e-06, -4.982521274545363e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


